pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool fuzz_trigger) public {
        // No adversarial helper required; proxiableUUID is a view with notDelegated,
        // but call succeeds in both because address(this) == __self (no proxy).
        // fuzz_trigger is unused but ensures the fuzzer drives inputs.
        vm.assume(fuzz_trigger || !fuzz_trigger); // always true, keeps fuzzing active
        (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSelector(C.proxiableUUID.selector));
        assertTrue(ok);
        bytes32 result = abi.decode(ret, (bytes32));
        bytes32 expected = keccak256(abi.encodePacked("eip1967.proxy.implementation")) - bytes32(uint256(1));
        assertTrue(result == expected);
    }
}

