pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address accessControl, address caller) public {
        // Ensure accessControl is not the zero address to test the initialization
        vm.assume(accessControl != address(0));
        // Deploy a minimal adversarial contract that reverts, simulating the behavior of
        // calling setSlopes. We will use this to distinguish between the two failure modes.
        // The buggy version calls the zero address, which will not revert, but succeed with no data.
        // The correct version calls accessControl, which will revert or return true/false.
        // However, we can simply see if the call to the zero address succeeds.
        c.initialize(accessControl);

        // The buggy version omits __Access_init, so accessControl stays zero.
        // When setSlopes is called, it calls IAccessControl(0).checkAccess(...)
        // Since address(0) has no code, the low-level staticcall succeeds and returns false.
        // Then Access._checkAccess will see !hasAccess and revert with AccessDenied().
        // The correct version calls the real accessControl, which will also revert or return false,
        // so we need to differentiate them by the REVERT REASON or by observing that accessControl
        // was stored correctly.
        // Since accessControl is a parameter, we can check if the stored accessControl equals it.
        // That directly tests the initialization integrity.
        // We can read the stored accessControl via the public getter? No, AccessStorageUtils is internal.
        // But the test says we must observe c through public surface.
        // Wait, the rule is: after initialization, any further privileged call must fail unless access is granted.
        // But we cannot observe the internal accessControl directly.
        // Alternative: We can use the fact that calling setSlopes in the buggy version will call address(0).
        // A call to address(0) with data will succeed silently, but the code inside _checkAccess will then
        // check the boolean result. Since address(0) returns false, it will revert with AccessDenied().
        // In the correct version, if accessControl is an EOA, it also returns false, reverting with AccessDenied().
        // So the revert reason is the same! We need a helper.
        // Adversarial helper: we deploy a contract that when called with checkAccess, returns true.
        // In the correct version, passing this helper as accessControl will make _checkAccess succeed,
        // whereas the buggy version will still call address(0) and fail.
        // This satisfies the adversarial counterparty rule.

        AccessGranter granter = new AccessGranter();
        // Initialize c with the granter's address as accessControl
        c.initialize(address(granter));

        // Now attempt to call setSlopes. The buggy version will call address(0).checkAccess(...),
        // which will return false, causing AccessDenied revert.
        // The correct version will call granter.checkAccess(...) which returns true,
        // so the call will succeed (only if kink is valid).
        // So we provide valid slopes.
        C.SlopeData memory slopes = C.SlopeData({
            kink: 5e26, // < 1e27 and != 0
            slope0: 100,
            slope1: 200
        });

        // We also need to prank as a caller; it doesn't matter, granter returns true for anyone.
        vm.prank(caller);
        bool ok;
        try c.setSlopes(address(0x1234), slopes) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

// Adversarial helper that grants access to anyone for any selector on any contract.
contract AccessGranter {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
}

