contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl) public {
        // 1. Restrict to admissible domain: accessControl must be a contract that can respond to checkAccess
        //    to avoid false positives. The initialize calls Access/IAccessControl; we cannot assume arbitrary addresses work.
        //    We deploy a minimal mock access control that returns true for any checkAccess.
        MockAccessControl mock = new MockAccessControl();
        // 2. Attempt to initialize
        bool success;
        try c.initialize(address(mock)) {
            success = true;
        } catch {
            success = false;
        }
        // 3. Assert: On reference, initialize SUCCEEDS and sets an initialized version.
        //    On buggy, it ALWAYS reverts, so success is false, meaning the initialized version remains unchanged.
        //    Check via _getInitializedVersion() visibility: it's internal, cannot be read. Instead, we rely on the
        //    fact that a second initialize call on an already-initialized reference contract will revert with
        //    InvalidInitialization(), while on the buggy contract a second call will also revert (always).
        //    To observe difference, we check that the reference contract cannot be re-initialized (revert on second call)
        //    while the buggy contract can? No, buggy always reverts.
        //    Actually, the invariant is: after a SUCCESSFUL initialize, subsequent initialize attempts revert.
        //    For the buggy contract, initialize NEVER succeeds, so a second call also reverts, making the property vacuously true.
        //    We need a property that holds on reference but fails on buggy.
        //    Reference: first initialize succeeds, second reverts.
        //    Buggy: first initialize always reverts, second reverts.
        //    To differentiate, we can assert that there EXISTS an input that makes initialize succeed (reference) but
        //    for buggy it always fails. So the property is: 'initialize never succeeds for ANY input' is false for reference
        //    but true for buggy.
        //    In fuzz terms: we assert that success is true for some input. This fails on buggy (always fails), passes on reference (succeeds for this mock).
        assertTrue(success);
    }
}

contract MockAccessControl {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
}

